/** Effective schema property, database column, and database-owned insert behavior. */
export interface ITableColumn {
  /** Logical property name used on schema instances. */
  readonly property: string;
  /** PostgreSQL column name before SQL identifier quoting. */
  readonly column: string;
  /** Schema input and output wire name, independently of the column override. */
  readonly wireName: string;
  /** Whether the field is marked as generated by the database. */
  readonly isGenerated: boolean;
  /** Whether the field is marked as having a database default. */
  readonly hasDbDefault: boolean;
  /** Whether generated or database-default metadata permits omission during insertion. */
  readonly isInsertOptional: boolean;
}
